/**
 * The phone app cannot read loose .sql files at runtime, so this script copies their text into
 * TypeScript modules that get bundled with the app:
 *   src/db/migrations/*.sql  ->  src/db/migrations/index.ts   (SPEC 6.1: numbered SQL migration files)
 * (More > AI disclosure shows a translated summary; the full statement is in AIDisclosure.md.)
 * It runs automatically before `typecheck`; a unit test fails if the generated files are out of date.
 * Pass --check to only verify (exit code 1 when a file would change).
 */
import { readdirSync, readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const check = process.argv.includes('--check');
const header = '// GENERATED by scripts/bundle-text.mjs. Do not edit by hand; run `pnpm --filter @emolens/mobile gen`.\n';

export function migrationsModule() {
  const dir = join(root, 'src/db/migrations');
  const files = readdirSync(dir).filter((f) => /^\d{3}_[a-z0-9_]+\.sql$/.test(f)).sort();
  const entries = files.map((f) => {
    const version = Number(f.slice(0, 3));
    return `  { version: ${version}, name: ${JSON.stringify(f)}, sql: ${JSON.stringify(readFileSync(join(dir, f), 'utf8'))} },`;
  });
  return `${header}export interface Migration { version: number; name: string; sql: string; }\n\n` +
    `export const MIGRATIONS: Migration[] = [\n${entries.join('\n')}\n];\n`;
}

const outputs = [
  [join(root, 'src/db/migrations/index.ts'), migrationsModule()],
];

let stale = false;
for (const [path, text] of outputs) {
  const current = existsSync(path) ? readFileSync(path, 'utf8') : '';
  if (current === text) continue;
  stale = true;
  if (!check) {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, text);
    console.log(`bundle-text: wrote ${path.slice(root.length + 1)}`);
  } else {
    console.error(`bundle-text: ${path.slice(root.length + 1)} is out of date (run the gen script)`);
  }
}
if (check && stale) process.exit(1);
